  location: string;
  imageUrl: string;
  targetAmount: number;
  raisedAmount: number;
  investorsCount: number;
  roi: number; // Return on Investment in %
  duration: number; // in months
  riskLevel: 'Faible' | 'Moyen' | 'Élevé';
}

export interface User {
  name: string;
  email: string;
  balance: number;
  portfolioValue: number;
}

