import { GoogleGenAI } from "@google/genai";
import { Project } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeProjectRisks = async (project: Project): Promise<string> => {
  try {
    const prompt = `
      Agis comme un expert agronome sénégalais expert en risque financier.
      Analyse brièvement ce projet pour un investisseur potentiel :

      Titre: ${project.title}
      Type: ${project.category}
      Lieu: ${project.location}
      Budget cible: ${project.targetAmount} FCFA
      ROI estimé: ${project.roi}%
      Durée: ${project.duration} mois
      Description: ${project.description}

      Donne une réponse courte (max 3 phrases) sur la viabilité et un conseil clé.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });

    return response.text || "Analyse indisponible pour le moment.";
  } catch (error) {
    console.error("Erreur Gemini:", error);
    return "Notre conseiller IA est momentanément indisponible.";
  }
};

export const chatWithAdvisor = async (userMessage: string): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: userMessage,
      config: {
        systemInstruction: "Tu es 'Baay Seddo AI', un assistant virtuel pour une plateforme de crowdfunding agricole au Sénégal. Tu parles français. Tu aides les investisseurs à comprendre l'agriculture (riziculture, aviculture, etc.) et l'investissement participatif. Sois concis, poli et encourageant."
      }
    });
    return response.text || "Je n'ai pas pu traiter votre demande.";
  } catch (error) {
    console.error("Erreur Chat:", error);
    return "Désolé, une erreur est survenue.";
  }
};

import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'outline' | 'ghost';
  size?: 'sm' | 'md' | 'lg';
  children: React.ReactNode;
}

export const Button: React.FC<ButtonProps> = ({ 
  variant = 'primary', 
  size = 'md', 
  className = '', 
  children, 
  ...props 
}) => {
  const baseStyles = "inline-flex items-center justify-center rounded-lg font-medium transition-colors focus:outline-none focus:ring-2 focus:ring-offset-2 disabled:opacity-50 disabled:pointer-events-none";

  const variants = {
    primary: "bg-green-700 text-white hover:bg-green-800 focus:ring-green-500 shadow-md",
    secondary: "bg-yellow-500 text-white hover:bg-yellow-600 focus:ring-yellow-400",
    outline: "border-2 border-green-700 text-green-700 hover:bg-green-50 focus:ring-green-500",
    ghost: "text-gray-600 hover:bg-gray-100 hover:text-gray-900"
  };

  const sizes = {
    sm: "h-9 px-3 text-sm",
    md: "h-11 px-6 text-base",
    lg: "h-14 px-8 text-lg"
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${sizes[size]} ${className}`} 
      {...props}
    >
      {children}
    </button>
  );
};

