        <div className="flex items-center text-slate-400 text-xs font-bold uppercase tracking-wider mb-4">
          <MapPin size={12} className="mr-1.5 text-green-600" />
          {project.location}
        </div>

        <p className="text-slate-500 text-sm mb-6 line-clamp-2 font-medium leading-relaxed">
          {project.description}
        </p>

        <div className="grid grid-cols-2 gap-4 mb-8">
            <div className="bg-slate-50 p-3 rounded-2xl border border-slate-100">
                <div className="flex items-center text-green-700 text-[10px] font-black uppercase tracking-widest mb-1">
                    <TrendingUp size={10} className="mr-1"/> ROI
                </div>
                <span className="font-black text-lg text-slate-800">+{project.roi}%</span>
            </div>
            <div className="bg-slate-50 p-3 rounded-2xl border border-slate-100">
                <div className="flex items-center text-slate-400 text-[10px] font-black uppercase tracking-widest mb-1">
                    <Clock size={10} className="mr-1"/> Durée
                </div>
                <span className="font-black text-lg text-slate-800">{project.duration}m</span>
